begin;
do $review_guard$
begin
 if (select count(*) from public.self_host_apps where slug in ('adminer', 'adminerevo', 'adnanh-webhook', 'ads-b-browser-screenshot', 'adsb-adsbexchange', 'adsb-flightaware', 'adsb-fr24feed', 'adsb-main') and published=true and self_hosting_status='self_hostable') <> 8 then raise exception 'Batch 22 app set changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adminer' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from 'https://github.com/vrana/adminer' and docker_image is not distinct from null) then raise exception 'adminer snapshot changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adminerevo' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from 'https://github.com/adminerevo/adminerevo' and docker_image is not distinct from null) then raise exception 'adminerevo snapshot changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adnanh-webhook' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from 'https://github.com/adnanh/webhook' and docker_image is not distinct from null) then raise exception 'adnanh-webhook snapshot changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='ads-b-browser-screenshot' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from 'https://github.com/tedder/browser-screenshot-service' and docker_image is not distinct from 'tedder42/browser-screenshot-service:latest') then raise exception 'ads-b-browser-screenshot snapshot changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adsb-adsbexchange' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from null and docker_image is not distinct from 'mikenye/adsbexchange') then raise exception 'adsb-adsbexchange snapshot changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adsb-flightaware' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from null and docker_image is not distinct from 'mikenye/piaware') then raise exception 'adsb-flightaware snapshot changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adsb-fr24feed' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from null and docker_image is not distinct from 'mikenye/fr24feed') then raise exception 'adsb-fr24feed snapshot changed since review'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adsb-main' and published=true and self_hosting_status='self_hostable' and source_code_url is not distinct from null and docker_image is not distinct from 'mikenye/readsb-protobuf') then raise exception 'adsb-main snapshot changed since review'; end if;
end;
$review_guard$;

