where app_id=(select id from public.self_host_apps where slug='adsb-main');

do $post_update_guard$
begin
 if (select count(*) from public.self_host_apps where slug in ('adminer', 'adnanh-webhook', 'ads-b-browser-screenshot', 'adsb-adsbexchange', 'adsb-flightaware', 'adsb-fr24feed', 'adsb-main') and published=true and self_hosting_status='self_hostable') <> 7 then raise exception 'Batch 22 active app corrections failed'; end if;
 if (select count(*) from public.self_host_app_resource_estimates e join public.self_host_apps a on a.id=e.app_id where a.slug in ('adminer', 'adminerevo', 'adnanh-webhook', 'ads-b-browser-screenshot', 'adsb-adsbexchange', 'adsb-flightaware', 'adsb-fr24feed', 'adsb-main') and e.ram_estimate_kind='estimated' and e.storage_estimate_kind='estimated' and e.ram_estimate_basis is not null and e.storage_estimate_basis is not null) <> 8 then raise exception 'Batch 22 estimate update check failed'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adminerevo' and published=false) then raise exception 'adminerevo publication cleanup failed'; end if;
end;
$post_update_guard$;
commit;
